    43→/// Deduplicates a vector and creates a mapping of original indices to deduplicated indices.
    44→///
    45→/// This function takes a vector of items and returns two vectors:
    46→/// 1. A vector of unique items (deduplicated vector)
    47→/// 2. A vector of indices that maps each item in the original vector to its position
    48→///    in the deduplicated vector
    49→fn deduplicate_with_indices<T: Eq + std::hash::Hash + Clone>(input: Vec<T>) -> (Vec<T>, Vec<u64>) {
    50→    let mut unique = Vec::new();
    51→    let mut map = HashMap::new();
    52→
    53→    let indices = input
    54→        .into_iter()
    55→        .map(|item| {
    56→            *map.entry(item.clone()).or_insert_with(|| {
    57→                let idx = unique.len();
    58→                unique.push(item);
    59→                idx
    60→            }) as u64
    61→        })
    62→        .collect();
    63→
    64→    (unique, indices)
    65→}
