    75→        cell_indices: &[CellIndex],
    76→        cells: Vec<CellRef>,
    77→        proofs_bytes: Vec<Bytes48Ref>,
    78→    ) -> Result<(), Error> {
    79→        let (deduplicated_commitments, row_indices) = deduplicate_with_indices(commitments);
    80→
    81→        // Validation
    82→        validation::verify_cell_kzg_proof_batch(
    83→            &deduplicated_commitments,
    84→            &row_indices,
    85→            cell_indices,
    86→            &cells,
    87→            &proofs_bytes,
    88→        )?;
    89→
    90→        // If there are no inputs, we return early with no error
    91→        if cells.is_empty() {
    92→            return Ok(());
    93→        }
    94→
    95→        // Deserialization
    96→        let row_commitments_ = deserialize_compressed_g1_points(deduplicated_commitments)?;
    97→        let proofs_ = deserialize_compressed_g1_points(proofs_bytes)?;
    98→        let coset_evals = deserialize_cells(cells)?;
    99→
   100→        // Computation
   101→        self.verifier_ctx
   102→            .kzg_multipoint_verifier
   103→            .verify_multi_opening(
   104→                &row_commitments_,
   105→                &row_indices,
   106→                cell_indices,
   107→                &coset_evals,
   108→                &proofs_,
   109→            )
   110→            .map_err(VerifierError::from)
   111→            .map_err(Into::into)
   112→    }
   113→}
   114→
   115→mod validation {
   116→    use kzg_multi_open::CommitmentIndex;
   117→
   118→    use crate::{
   119→        constants::CELLS_PER_EXT_BLOB, verifier::VerifierError, Bytes48Ref, CellIndex, CellRef,
   120→    };
   121→
   122→    /// Validation logic for `verify_cell_kzg_proof_batch`
   123→    pub fn verify_cell_kzg_proof_batch(
   124→        deduplicated_commitments_bytes: &[Bytes48Ref],
   125→        commitment_indices: &[CommitmentIndex],
   126→        cell_indices: &[CellIndex],
   127→        cells: &[CellRef],
   128→        proofs_bytes: &[Bytes48Ref],
   129→    ) -> Result<(), VerifierError> {
   130→        // All inputs must have the same length according to the specs.
   131→        let same_length = (commitment_indices.len() == cell_indices.len())
   132→            & (commitment_indices.len() == cells.len())
   133→            & (commitment_indices.len() == proofs_bytes.len());
   134→        if !same_length {
   135→            return Err(VerifierError::BatchVerificationInputsMustHaveSameLength {
   136→                commitment_indices_len: commitment_indices.len(),
   137→                cell_indices_len: cell_indices.len(),
   138→                cells_len: cells.len(),
   139→                proofs_len: proofs_bytes.len(),
   140→            });
   141→        }
   142→
